css:
/* 轻量动态拟物 · Soft Touch
   介于扁平与拟物之间：软胶按钮、果冻回弹、柔和内外阴影，
   再叠一层极细噪点与柔光，去掉 AI 界面的塑料感。纯 CSS。 */

html[data-theme] {
  color-scheme: light;
  --bg: #f4f1ec;
  --ink: #2b2723; --muted: #6a6259; --dim: #928a80;
  --soft: #3d3731; --meta: #6a6259; --bright: #1a1713;
  --line: rgba(255, 255, 255, 0.9); --line2: rgba(43, 39, 35, 0.08);
  --accent: #ff7a59; --accent2: #ffb59f; --accentText: #ffffff;
  --good: #4fa97b; --warn: #d08a2c;
  --glow1: rgba(255, 122, 89, 0.16); --glow2: rgba(255, 181, 159, 0.18);
  --panel: rgba(255, 255, 255, 0.72); --panel2: rgba(255, 255, 255, 0.9);
  --dock1: rgba(255, 253, 250, 0.9); --dock2: rgba(250, 245, 238, 0.86);
  --glass: rgba(255, 255, 255, 0.62);
  --track: rgba(43, 39, 35, 0.08); --scroll: #c9bfb2; --coverbg: #ebe4da;
  --menu: rgba(255, 253, 250, 0.96); --menu1: #ffffff; --menu2: #fbf7f2; --chev: #8a8177;
  --edge: rgba(255, 255, 255, 0.95); --edge2: rgba(255, 122, 89, 0.24);
  --hover: rgba(255, 255, 255, 0.72); --tick: rgba(43, 39, 35, 0.1);
  --inset: rgba(255, 255, 255, 0.98); --wordactive: #1a1713; --swborder: rgba(43, 39, 35, 0.16);
  --shadow-dock: 0 20px 44px -26px rgba(80, 60, 44, 0.35), 0 2px 0 rgba(255, 255, 255, 0.9) inset;
  --serif: "Segoe UI Variable Display", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --bottom: 138px;
  --shell-nav: rgba(255, 255, 255, 0.6); --shell-nav2: rgba(255, 255, 255, 0.3);
  --shell-navin: #2b2723; --shell-navmuted: #6a6259; --shell-navline: rgba(43, 39, 35, 0.07);
}

html[data-theme] body {
  background:
    radial-gradient(760px 520px at 10% -8%, #ffe9df, transparent 62%),
    radial-gradient(680px 520px at 92% 6%, #e9f0ff, transparent 62%),
    linear-gradient(170deg, #f8f5f1, #f1ece5 58%, #efe9e2);
}
/* 细噪点 + 柔光 */
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: 0.5;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.22'/></svg>");
  mix-blend-mode: soft-light;
}

/* 侧栏：一块被压软的硅胶 */
html[data-theme] .sidebar {
  margin: 14px 0 14px 14px; padding: 22px 14px; border: 1px solid rgba(255, 255, 255, 0.85);
  border-radius: 28px; background: linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(250, 245, 238, 0.6));
  box-shadow: 0 22px 44px -30px rgba(80, 60, 44, 0.4), inset 0 2px 0 #fff, inset 0 -10px 20px rgba(80, 60, 44, 0.05);
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
}
html[data-theme] .brand { padding: 2px 8px 20px; border-bottom: 1px solid rgba(43, 39, 35, 0.07); margin-bottom: 14px; }
html[data-theme] .nav button { border-radius: 14px; color: #6a6259; }
html[data-theme] .nav button:hover { background: rgba(255, 255, 255, 0.85); color: #2b2723; }
html[data-theme] .nav button.active {
  color: #2b2723; font-weight: 600; background: #ffffff;
  box-shadow: 0 8px 18px -14px rgba(80, 60, 44, 0.5), inset 0 1px 0 #fff;
}

/* 顶栏 */
html[data-theme] .topbar {
  margin-top: 14px; padding: 0 18px; height: 64px; border: 1px solid rgba(255, 255, 255, 0.9);
  border-radius: 22px; background: rgba(255, 255, 255, 0.6);
  box-shadow: 0 16px 36px -30px rgba(80, 60, 44, 0.4), inset 0 1px 0 #fff;
  backdrop-filter: blur(22px) saturate(150%); -webkit-backdrop-filter: blur(22px) saturate(150%);
}
html[data-theme] .search-global { border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 999px; background: rgba(255, 255, 255, 0.72); box-shadow: inset 0 2px 6px rgba(80, 60, 44, 0.08); }
html[data-theme] .icon-btn { border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 999px; background: rgba(255, 255, 255, 0.72); }

/* 首页 */
html[data-theme] .ledger-mast {
  margin-top: 22px; padding: 32px; border: 1px solid rgba(255, 255, 255, 0.95); border-radius: 30px;
  background:
    radial-gradient(520px 260px at 86% -12%, rgba(255, 255, 255, 0.95), transparent 64%),
    linear-gradient(170deg, rgba(255, 255, 255, 0.85), rgba(255, 236, 227, 0.62));
  box-shadow: 0 34px 60px -44px rgba(80, 60, 44, 0.5), inset 0 2px 0 #fff;
  backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(38px, 5vw, 68px); line-height: 1.04; letter-spacing: -1.4px; color: #2b2723;
}
html[data-theme] .ledger-mast h1 em { color: #ff7a59; }
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #6a6259; }

/* 卡片：柔软，不抢戏 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 24px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.8), rgba(252, 248, 243, 0.66));
  box-shadow: 0 24px 44px -38px rgba(80, 60, 44, 0.45), inset 0 1px 0 #fff;
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
}
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover { transform: translateY(-2px) scale(1.005); }
/* 软胶按钮：按下去会回弹 */
html[data-theme] .btn {
  border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 999px;
  background: linear-gradient(180deg, #fff7f3, #ffd8cc); color: #4a2a20; font-weight: 600;
  box-shadow: inset 0 2px 0 #fff, inset 0 -3px 6px rgba(255, 122, 89, 0.2), 0 10px 20px -16px rgba(80, 60, 44, 0.6);
  transition: transform 0.16s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.16s;
}
html[data-theme] .btn.primary { background: linear-gradient(180deg, #ff9c83, #ff7a59); color: #fff; }
html[data-theme] .btn:hover { transform: translateY(-1px) scale(1.02); }
html[data-theme] .btn:active { transform: scale(0.965); box-shadow: inset 0 4px 10px rgba(80, 60, 44, 0.25); }

/* 统计 */
html[data-theme] #page-stats .page-head {
  margin: 18px 0; padding: 28px 30px; border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 30px;
  background: linear-gradient(170deg, rgba(255, 255, 255, 0.85), rgba(255, 240, 233, 0.6));
  box-shadow: 0 30px 56px -44px rgba(80, 60, 44, 0.5), inset 0 2px 0 #fff;
}
html[data-theme] #page-stats .page-head h1 { font-size: clamp(30px, 4.2vw, 50px); letter-spacing: -1.2px; color: #2b2723; }
html[data-theme] #page-stats .eyebrow { color: #ff7a59; letter-spacing: 0.28em; }
html[data-theme] #page-stats .stat {
  border: 1px solid rgba(255, 255, 255, 0.95); border-radius: 24px; padding: 20px 22px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.86), rgba(255, 240, 234, 0.6));
  box-shadow: 0 20px 38px -32px rgba(80, 60, 44, 0.45), inset 0 2px 0 #fff;
}
html[data-theme] #page-stats .stat:before { content: none; }
html[data-theme] #page-stats .stat label { letter-spacing: 0.15em; color: #6a6259; font-weight: 600; }
html[data-theme] #page-stats .stat strong { font-size: 32px; font-weight: 700; color: #2b2723; background: none; -webkit-text-fill-color: #2b2723; }
html[data-theme] #page-stats .stat em { color: #928a80; }
html[data-theme] #page-stats .stat-bar { border-radius: 16px; background: rgba(255, 255, 255, 0.62); }
html[data-theme] #page-stats .stat-track { height: 7px; border-radius: 999px; background: rgba(43, 39, 35, 0.07); box-shadow: inset 0 2px 4px rgba(80, 60, 44, 0.12); }
html[data-theme] #page-stats .stat-track i { border-radius: 999px; background: linear-gradient(90deg, #ff9c83, #ff7a59); box-shadow: 0 2px 8px rgba(255, 122, 89, 0.35); }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 30px; padding: 26px 30px; border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 30px;
  background: linear-gradient(170deg, rgba(255, 255, 255, 0.85), rgba(240, 245, 255, 0.55));
  box-shadow: 0 30px 56px -44px rgba(80, 60, 44, 0.5), inset 0 2px 0 #fff;
}
html[data-theme] #page-stats .year-title { font-size: 42px; color: #2b2723; background: none; -webkit-text-fill-color: #2b2723; }
html[data-theme] #page-stats #echoYear { border: 1px solid #fff; border-radius: 999px; background: rgba(255, 255, 255, 0.8); color: #2b2723; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 22px; background: rgba(255, 255, 255, 0.65); }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid rgba(255, 255, 255, 0.9); border-radius: 14px; background: rgba(255, 255, 255, 0.78); color: #2b2723;
}

/* 播放舱 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 18px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 1px solid rgba(255, 255, 255, 0.95); border-radius: 28px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.9), rgba(250, 244, 238, 0.84));
    box-shadow: 0 26px 50px -30px rgba(80, 60, 44, 0.45), inset 0 2px 0 #fff;
    backdrop-filter: blur(26px) saturate(150%);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn {
  border-radius: 50%; border: 1px solid #fff; color: #4a2a20;
  background: radial-gradient(circle at 34% 26%, #fff2ec, #ffb59f 52%, #ff7a59);
  box-shadow: inset 0 3px 6px rgba(255, 255, 255, 0.9), 0 10px 20px -12px rgba(255, 122, 89, 0.6);
}
html[data-theme] .mini-player { border: 1px solid #fff; border-radius: 22px; background: rgba(255, 253, 250, 0.86); box-shadow: 0 18px 36px -28px rgba(80, 60, 44, 0.45); }

html[data-theme] .cue.active .word { color: #1a1713; background: #ffe1d7; border-radius: 6px; }
html[data-theme] ::-webkit-scrollbar-thumb { background: #d8cec1; border-radius: 999px; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: linear-gradient(160deg, #f7f3ee 0%, #f1eae2 48%, #fdf9f4 100%); color: #2b2723; }
html[data-theme] .wp-bg { filter: blur(40px) saturate(90%) brightness(1.45) contrast(.94); opacity: .32; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(247,243,238,.94) 0%, rgba(247,243,238,.84) 52%, rgba(253,249,244,.74) 78%, rgba(247,243,238,.95) 100%), radial-gradient(66% 54% at 80% 18%, rgba(255,122,89,.16), transparent 64%); }
html[data-theme] .wp-kicker { color: #c2492a; font-weight:700;letter-spacing:.2em; }
html[data-theme] .wp-title { color: #2b2723; font-weight:700;letter-spacing:-.03em; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(43,39,35,.68); }
html[data-theme] .wp-cue.active::before { background: linear-gradient(180deg, #ff7a59, #ffb59f); box-shadow: inset 2px 2px 6px rgba(255,255,255,.8), 0 6px 16px -8px rgba(255,122,89,.9); width:clamp(5px,.36vw,7px);border-radius:99px; }
html[data-theme] .wp-cue.active .wp-en { color: #2b2723; text-shadow: 0 2px 16px rgba(43,39,35,.16); font-weight:700; }
html[data-theme] .wp-word.past { color: #2b2723; }
html[data-theme] .wp-word.active { color: #c2492a; background-image: linear-gradient(180deg, transparent 60%, rgba(255,122,89,.34) 60%, rgba(255,181,159,.22) 94%, transparent 94%); text-shadow: 0 0 16px rgba(255,122,89,.35); border-radius:8px; }
html[data-theme] .wp-zh { color: rgba(43,39,35,.6); font-weight:400; }
html[data-theme] .wp-label { color: rgba(43,39,35,.4); }
html[data-theme] .wpbtn { background: linear-gradient(180deg, #ffffff, #efe8e0); border-color: rgba(255,255,255,.9); color: #2b2723; border-radius:999px;box-shadow:inset 0 1px 0 #fff,0 10px 20px -12px rgba(43,39,35,.5);font-weight:600; }
html[data-theme] .wpbtn:hover { background: linear-gradient(180deg, #ffb59f, #ff7a59); border-color: rgba(255,255,255,.9); color: #ffffff; }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dshead h4 { color: var(--soft, var(--muted)); }
html[data-theme] .dstile { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--ink); border-radius: 12px; }
html[data-theme] .dstile svg { stroke: var(--muted); }
html[data-theme] .dstile:hover { background: var(--hover, var(--panel2)); border-color: var(--accent); color: var(--ink); }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); }
html[data-theme] .dslabel { color: var(--muted); }
html[data-theme] .dspill, html[data-theme] .dsmute { background: var(--panel2, var(--panel)); border-color: var(--line); color: var(--soft, var(--ink)); }
html[data-theme] .dspill.on { color: var(--accent); border-color: var(--accent); }
html[data-theme] .dsrange { accent-color: var(--accent); }
html[data-theme] .iconbtn { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--muted); }
